let meterContext=null,meterFrame=null,meterSource=null;const busyDevices=new Set();
function feedback(kind,text){document.getElementById(kind+'Status').textContent=text}
function liveTrack(kind){return stream?.getTracks().find(t=>t.kind===kind&&t.readyState==='live')}
function sync(){const mic=!!liveTrack('audio');$('previewMic').lastElementChild.textContent=mic?(micOn?'Mic on':'Mic muted'):'Enable mic';$('micToggle').lastElementChild.textContent=mic?(micOn?'Microphone on':'Microphone muted'):'Enable microphone';for(const id of ['previewMic','micToggle']){$(id).classList.toggle('is-muted',!micOn||!mic);$(id).setAttribute('aria-pressed',mic&&micOn)}$('previewCamera').lastElementChild.textContent=camOn?'Camera on':'Enable camera';$('cameraToggle').lastElementChild.textContent=camOn?'Camera on':'Camera off';for(const id of ['previewVideo','roomVideo']){$(id).srcObject=stream;$(id).classList.toggle('active',camOn&&!!liveTrack('video'));if(camOn)$(id).play().catch(()=>{})}stream?.getAudioTracks().forEach(t=>t.enabled=micOn);stream?.getVideoTracks().forEach(t=>t.enabled=camOn)}
async function devices(){if(!navigator.mediaDevices?.enumerateDevices)return;const all=await navigator.mediaDevices.enumerateDevices();for(const [id,kind,label] of [['microphone','audioinput','microphone'],['speaker','audiooutput','speakers'],['camera','videoinput','camera']]){const select=$(id),previous=select.value;select.replaceChildren(new Option('System default '+label,''));all.filter(d=>d.kind===kind&&d.deviceId).forEach((d,i)=>select.add(new Option(d.label||label+' '+(i+1),d.deviceId)));select.value=previous;if(select.selectedIndex<0)select.selectedIndex=0}if(!('setSinkId' in AudioContext.prototype)){$('speaker').disabled=true;$('chooseSpeaker').disabled=true;feedback('speaker','This browser uses your system output. Choose speakers in Windows sound settings, then test them here.')}}
function deviceError(error,kind){const name=kind==='mic'?'Microphone':'Camera';const messages={NotAllowedError:name+' permission is blocked or unavailable in this browser. Allow it in site settings, or open this local URL in Chrome or Edge.',NotFoundError:'No '+name.toLowerCase()+' was found. Connect a device and refresh the device list.',NotReadableError:name+' could not start. Close other apps using it and check Windows device permissions.',OverconstrainedError:'That device is unavailable. Select the system default and try again.'};feedback(kind,messages[error.name]||name+' could not start: '+error.message)}
async function enableDevice(kind){if(busyDevices.has(kind))return false;const video=kind==='camera',trackKind=video?'video':'audio',id=video?'camera':'microphone';if(!navigator.mediaDevices?.getUserMedia){feedback(kind,'Device access is unavailable here. Open http://localhost:5173 in Chrome or Edge.');return false}busyDevices.add(kind);feedback(kind,'Waiting for '+(video?'camera':'microphone')+' permission…');try{const selected=$(id).value;const next=await navigator.mediaDevices.getUserMedia({audio:!video?(selected?{deviceId:{exact:selected}}:true):false,video:video?(selected?{deviceId:{exact:selected}}:true):false});stream??=new MediaStream();if(!video)stopMeter();stream.getTracks().filter(t=>t.kind===trackKind).forEach(t=>{t.stop();stream.removeTrack(t)});next.getTracks().forEach(t=>{stream.addTrack(t);t.onended=()=>{if(video)camOn=false;else{micOn=false;stopMeter()}sync();feedback(kind,'Device disconnected. Enable it again or choose another device.')}});if(video)camOn=true;else micOn=true;sync();await devices();feedback(kind,video?'Camera ready — your live preview is visible.':'Microphone ready. Select Test microphone and speak.');return true}catch(error){deviceError(error,kind);return false}finally{busyDevices.delete(kind)}}
function stopMeter(){cancelAnimationFrame(meterFrame);meterSource?.disconnect();meterSource=null;if(meterContext){meterContext.close().catch(()=>{});meterContext=null}$('micLevel').value=0;$('testMic').textContent='Test microphone'}
async function testMicrophone(){if(meterContext){stopMeter();feedback('mic','Input test stopped. Your microphone remains enabled.');return}if(!liveTrack('audio')&&!await enableDevice('mic'))return;micOn=true;sync();try{meterContext=new AudioContext();await meterContext.resume();meterSource=meterContext.createMediaStreamSource(new MediaStream([liveTrack('audio')]));const analyser=meterContext.createAnalyser();analyser.fftSize=256;meterSource.connect(analyser);const data=new Uint8Array(analyser.fftSize);function tick(){analyser.getByteTimeDomainData(data);const rms=Math.sqrt(data.reduce((sum,x)=>sum+((x-128)/128)**2,0)/data.length);$('micLevel').value=Math.min(100,rms*400);meterFrame=requestAnimationFrame(tick)}tick();$('testMic').textContent='Stop input test';feedback('mic','Speak now — the input meter should move. Your voice is not played through the speakers.')}catch(error){stopMeter();feedback('mic','Unable to start input test: '+error.message)}}
async function outputContext(){audioContext??=new AudioContext();await audioContext.resume();if(audioContext.setSinkId)await audioContext.setSinkId($('speaker').value);return audioContext}
async function testSpeakers(){try{const context=await outputContext();for(let i=0;i<3;i++){const osc=context.createOscillator(),gain=context.createGain(),start=context.currentTime+i*.35;osc.frequency.value=[523,659,784][i];gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(.12,start+.02);gain.gain.exponentialRampToValueAtTime(.001,start+.28);osc.connect(gain).connect(context.destination);osc.start(start);osc.stop(start+.3)}feedback('speaker','Playing three chimes through '+$('speaker').selectedOptions[0].text+'. If silent, check your volume, browser sound permission, and Windows output device.')}catch(error){feedback('speaker','Unable to play through that output: '+error.message+'. Choose System default and try again.')}}
async function toggleMic(){if(!liveTrack('audio'))return enableDevice('mic');micOn=!micOn;if(!micOn)stopMeter();sync();feedback('mic',micOn?'Microphone enabled.':'Microphone muted.')}
async function toggleCamera(){if(!liveTrack('video'))return enableDevice('camera');camOn=!camOn;sync();feedback('camera',camOn?'Camera preview on.':'Camera preview off.')}
document.addEventListener('DOMContentLoaded',()=>{$('previewMic').onclick=toggleMic;$('micToggle').onclick=toggleMic;$('previewCamera').onclick=toggleCamera;$('cameraToggle').onclick=toggleCamera;$('enableMic').onclick=()=>enableDevice('mic');$('testMic').onclick=testMicrophone;$('testCamera').onclick=()=>enableDevice('camera');$('testAudio').onclick=testSpeakers;$('permission').onclick=()=>devices().then(()=>setStatus('Device list refreshed. Use the separate input, output, and camera controls.')).catch(e=>setStatus(e.message));$('microphone').onchange=()=>enableDevice('mic');$('camera').onchange=()=>enableDevice('camera');$('speaker').onchange=async()=>{try{await outputContext();feedback('speaker','Output selected. Press Test speakers to hear a chime.')}catch(e){feedback('speaker','Could not select this output: '+e.message)}};$('chooseSpeaker').onclick=async()=>{if(!navigator.mediaDevices?.selectAudioOutput){feedback('speaker','Choose a listed output above. Enable your microphone to reveal device names, or select the output in Windows sound settings.');return}try{const device=await navigator.mediaDevices.selectAudioOutput();await devices();if(![...$('speaker').options].some(o=>o.value===device.deviceId))$('speaker').add(new Option(device.label,device.deviceId));$('speaker').value=device.deviceId;await outputContext();feedback('speaker','Output selected. Test your speakers now.')}catch(e){feedback('speaker','Output selection cancelled or blocked. Use System default or Windows sound settings.')}};navigator.mediaDevices?.addEventListener('devicechange',()=>devices().catch(()=>{}));});
